#!/usr/bin/env python3
"""Write Expose's pixel tables from its artwork in src/third_party/expose/art:
the window buttons (ExposeButtons.h) and check boxes and radio buttons
(ExposeMarks.h). Needs rsvg-convert and Pillow.

    python3 -I tools/make-expose-art.py
"""

import io
import os
import re
import subprocess
import xml.etree.ElementTree as ElementTree

from PIL import Image

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
EXPOSE = os.path.join(ROOT, "src", "third_party", "expose")
ART = os.path.join(EXPOSE, "art")
SHEETS = {}

HEADER = """/*
 * Generated by tools/make-expose-art.py from the Expose artwork by Mark
 * Whittaker. Distributed under the terms of the GNU GPL, version 3 or later.
 */
"""


def render(svg, element):
	data = subprocess.run(["rsvg-convert", "-i", element, os.path.join(ART, svg)],
		check=True, capture_output=True).stdout
	return Image.open(io.BytesIO(data)).convert("RGBA")


def matrix_of(element):
	"""An element's transform as (a, b, c, d, e, f)."""
	text = element.get("transform", "")
	numbers = [float(n) for n in re.findall(r"-?[\d.]+(?:e-?\d+)?", text)]
	if text.startswith("translate"):
		return (1, 0, 0, 1, numbers[0], numbers[1] if len(numbers) > 1 else 0)
	if text.startswith("matrix"):
		return tuple(numbers)
	return (1, 0, 0, 1, 0, 0)


def combine(m, n):
	return (m[0] * n[0] + m[2] * n[1], m[1] * n[0] + m[3] * n[1],
		m[0] * n[2] + m[2] * n[3], m[1] * n[2] + m[3] * n[3],
		m[0] * n[4] + m[2] * n[5] + m[4], m[1] * n[4] + m[3] * n[5] + m[5])


def shapes(element, matrix):
	"""The bounds of each rectangle and circle in an element."""
	matrix = combine(matrix, matrix_of(element))
	tag = element.tag.split("}")[-1]
	if tag == "rect":
		x, y = float(element.get("x", 0)), float(element.get("y", 0))
		box = (x, y, x + float(element.get("width")), y + float(element.get("height")))
	elif tag == "circle":
		r = float(element.get("r"))
		x, y = float(element.get("cx")), float(element.get("cy"))
		box = (x - r, y - r, x + r, y + r)
	else:
		box = None
	if box is not None:
		yield (matrix[0] * box[0] + matrix[2] * box[1] + matrix[4],
			matrix[1] * box[0] + matrix[3] * box[1] + matrix[5],
			matrix[0] * box[2] + matrix[2] * box[3] + matrix[4],
			matrix[1] * box[2] + matrix[3] * box[3] + matrix[5])
	for child in element:
		yield from shapes(child, matrix)


def find(element, wanted, matrix=(1, 0, 0, 1, 0, 0)):
	if element.get("id") == wanted:
		return element, matrix
	matrix = combine(matrix, matrix_of(element))
	for child in element:
		found = find(child, wanted, matrix)
		if found is not None:
			return found
	return None


def crop_mark(svg, element):
	"""A mark, cut from a drawing of the whole sheet: rsvg-convert -i leaves out
	parts of some of these groups, such as a check box's frame and tick. The size
	comes from what -i measures, which counts the strokes."""
	path = os.path.join(ART, svg)
	if svg not in SHEETS:
		data = subprocess.run(["rsvg-convert", path], check=True,
			capture_output=True).stdout
		SHEETS[svg] = (Image.open(io.BytesIO(data)).convert("RGBA"),
			ElementTree.parse(path).getroot())
	sheet, root = SHEETS[svg]

	found, matrix = find(root, element)
	boxes = list(shapes(found, matrix))
	left = min(b[0] for b in boxes)
	top = min(b[1] for b in boxes)
	right = max(b[2] for b in boxes)
	bottom = max(b[3] for b in boxes)

	width, height = render(svg, element).size
	x = round((left + right - width) / 2)
	y = round((top + bottom - height) / 2)
	return sheet.crop((x, y, x + width, y + height))


def button(svg, state):
	"""A 22 x 22 button, from its nine pieces: edges of 3 round 16."""
	image = Image.new("RGBA", (22, 22))
	columns = (("left", 0, 3), ("", 3, 16), ("right", 19, 3))
	rows = (("top", 0, 3), ("", 3, 16), ("bottom", 19, 3))
	for row, y, height in rows:
		for column, x, width in columns:
			part = row + column or "center"
			piece = render(svg, state + "-" + part)
			image.paste(piece.crop((0, 0, width, height)), (x, y))
	return image


def table(name, image):
	width, height = image.size
	lines = ["static const uint32 %s[%d] = {" % (name, width * height)]
	data = image.tobytes()
	pixels = [(data[i + 3] << 24) | (data[i] << 16) | (data[i + 1] << 8) | data[i + 2]
		for i in range(0, len(data), 4)]
	for start in range(0, len(pixels), width):
		lines.append("\t" + ", ".join("0x%08x" % p
			for p in pixels[start:start + width]) + ",")
	lines.append("};")
	return "\n".join(lines) + "\n"


def buttons():
	out = [HEADER, "#ifndef EXPOSE_BUTTONS_H\n#define EXPOSE_BUTTONS_H\n\n",
		"// ARGB, row by row: the large ones for most windows, the small ones "
		"for floating\n// windows\n",
		"static const int32 kLargeButton = 22;\n",
		"static const int32 kSmallButton = 16;\n\n"]
	for svg, name in (("close.svg", "Close"), ("maximize.svg", "Zoom"),
			("minimize.svg", "Minimize")):
		for state, stateName in (("active", "Active"), ("pressed", "Pressed"),
				("inactive", "Inactive")):
			image = button(svg, state)
			out.append(table("k%s%sLarge" % (name, stateName), image))
			small = image.resize((16, 16), Image.LANCZOS)
			out.append(table("k%s%sSmall" % (name, stateName), small))
	out.append("\n#endif	// EXPOSE_BUTTONS_H\n")
	path = os.path.join(EXPOSE, "decorator", "ExposeButtons.h")
	with open(path, "w") as f:
		f.write("".join(out))


def marks():
	out = [HEADER, "#ifndef EXPOSE_MARKS_H\n#define EXPOSE_MARKS_H\n\n",
		"// ARGB, row by row\n", "static const int32 kMarkSize = 16;\n\n"]
	checks = (("checkbox-normal", "CheckOff"),
		("checkbox-focused", "CheckOffHover"),
		("checkbox-checked-normal", "CheckOn"),
		("checkbox-checked-focused", "CheckOnHover"),
		("checkbox-tristate-normal", "CheckMixed"),
		("checkbox-tristate-focused", "CheckMixedHover"),
		("radio-normal", "RadioOff"),
		("radio-focused", "RadioOffHover"),
		("radio-checked-normal", "RadioOn"),
		("radio-checked-focused", "RadioOnHover"))
	for svg, suffix, elements in (("ExposeAirDark.svg", "Dark", checks),
			("ExposeDark.svg", "Light", checks + (("scursor-normal", "Thumb"),
				("scursor-focused", "ThumbHover")))):
		for element, name in elements:
			image = crop_mark(svg, element).resize((16, 16), Image.LANCZOS)
			out.append(table("k" + name + suffix, image))
	out.append("\n#endif	// EXPOSE_MARKS_H\n")
	path = os.path.join(EXPOSE, "controllook", "ExposeMarks.h")
	with open(path, "w") as f:
		f.write("".join(out))


buttons()
marks()
